const baseUrl='https://yestrades.co.uk';
function seoFor(path,s){
 let title='Local Trades in Edinburgh & West Lothian | Yes Trades';
 let description='Trusted local plumbers, electricians, Gas Safe engineers, property maintenance and home renovations across Edinburgh, Livingston and West Lothian.';
 let keywords='local trades Edinburgh, home services Livingston, property maintenance West Lothian, plumbers Edinburgh, electricians Livingston, Gas Safe engineers';
 if(s){title=`${s.title} Edinburgh & Livingston | Yes Trades`;description=`${s.title} in Edinburgh, Livingston and West Lothian. ${s.desc} Request a clear quote from Yes Trades.`;keywords=`${s.title.toLowerCase()} Edinburgh, ${s.title.toLowerCase()} Livingston, ${s.title.toLowerCase()} West Lothian, local ${s.category.toLowerCase()}`;}
 else if(path==='/services'){title='Home Repair & Renovation Services | Yes Trades';description='Browse plumbing, electrical, boiler, heating, landlord certificate, cleaning and renovation services in Edinburgh and West Lothian.';}
 else if(path==='/landlords'){title='Landlord Certificates & Property Services | Yes Trades';description='EICR, CP12 gas safety, EPC, PAT testing, legionella assessments and landlord maintenance across Edinburgh and West Lothian.';keywords='landlord certificates Edinburgh, EICR Livingston, CP12 West Lothian, EPC Edinburgh, PAT testing Livingston';}
 else if(path==='/areas'){title='Local Trades Across Edinburgh & West Lothian | Yes Trades';description='Check Yes Trades availability in Edinburgh, Livingston, Bathgate, Broxburn, Linlithgow and surrounding areas.';}
 else if(path==='/about'){title='About Our Local Trades Team | Yes Trades';description='About Yes Trades, supporting homeowners, landlords and property managers across Edinburgh and West Lothian.';}
 else if(path==='/contact'){title='Contact Yes Trades | Edinburgh & West Lothian';description='Contact Yes Trades for repairs, boiler work, electrical services, landlord certificates and home renovation quotes.';}
 return {title,description,keywords};
}
function setSEO(path,s){const seo=seoFor(path,s);document.title=seo.title;setMeta('name','description',seo.description);setMeta('name','keywords',seo.keywords);setMeta('property','og:title',seo.title);setMeta('property','og:description',seo.description);setMeta('property','og:url',baseUrl+(path==='/'?'':path));setMeta('name','twitter:title',seo.title);setMeta('name','twitter:description',seo.description);document.querySelector('link[rel="canonical"]').href=baseUrl+(path==='/'?'/':path);document.querySelectorAll('script[data-seo-schema]').forEach(x=>x.remove());addSchema(s?serviceSchema(s,path):businessSchema());if(s)addSchema(breadcrumbSchema(s,path));if(path.startsWith('/book/')){document.querySelector('link[rel="canonical"]').href=baseUrl+'/services/'+s.slug;setMeta('name','robots','noindex,follow')}else{setMeta('name','robots','index,follow,max-image-preview:large')}}
function setMeta(attr,key,value){let el=document.querySelector(`meta[${attr}="${key}"]`);if(!el){el=document.createElement('meta');el.setAttribute(attr,key);document.head.appendChild(el)}el.content=value}
function addSchema(data){const el=document.createElement('script');el.type='application/ld+json';el.dataset.seoSchema='true';el.textContent=JSON.stringify(data);document.head.appendChild(el)}
function businessSchema(){return {'@context':'https://schema.org','@type':['LocalBusiness','HomeAndConstructionBusiness'],name:'Yes Trades',url:baseUrl,logo:baseUrl+'/assets/img/6a785bf9c2d66.png',telephone:'+441316293987',email:'info@yestrades.co.uk',vatID:'GB526611404',areaServed:['Edinburgh','Livingston','Bathgate','Broxburn','Linlithgow','West Lothian'],openingHoursSpecification:[{'@type':'OpeningHoursSpecification',dayOfWeek:['Monday','Tuesday','Wednesday','Thursday','Friday'],opens:'08:00',closes:'18:00'},{'@type':'OpeningHoursSpecification',dayOfWeek:'Saturday',opens:'09:00',closes:'14:00'}]}}
function serviceSchema(s,path){return {'@context':'https://schema.org','@type':'Service',name:s.title,description:s.desc,serviceType:s.title,url:baseUrl+path,provider:{'@type':'LocalBusiness',name:'Yes Trades',url:baseUrl,telephone:'+441316293987'},areaServed:['Edinburgh','Livingston','West Lothian']}}
