function bindBooking(s){const box=document.querySelector('#booking-step');box.querySelector('[data-next]')?.addEventListener('click',()=>{box.querySelectorAll('input,select,textarea').forEach(x=>{if(x.name)bookingState.answers[x.name]=x.value});bookingState.step++;bookingStep(s)});box.querySelector('[data-back]')?.addEventListener('click',()=>{bookingState.step--;bookingStep(s)});box.querySelector('[data-confirm]')?.addEventListener('click',()=>{box.innerHTML=`<div class="confirmation"><div class="confirm-icon">OK</div><h2>Booking journey complete</h2><p>This is the confirmation screen customers see after Stripe verifies a successful payment.</p><span class="ref">Example reference: YT-2026-1042</span><p>An email and SMS would contain the service, address, appointment, VAT receipt and contact details.</p><a class="btn" href="/">Return home</a></div>`})}
