function easyBookingPage(s){if(!startingPrices[s.slug])return servicePage(s);const q=serviceQuestions(s),gross=startingPrices[s.slug],net=(gross/1.2).toFixed(2),vat=(gross-net).toFixed(2);return `${header()}<main class="easy-shell"><div class="wrap"><div class="easy-head"><div><div class="eyebrow">Fast online booking</div><h1>Book ${s.title}</h1><p>Answer the details and choose a date on this page. Address and payment come together in your booking cart.</p></div><div class="two-step"><span>1</span> Job & date <b>-></b><span style="background:#9ba59d">2</span> Address & payment</div></div><div class="easy-grid"><form class="easy-form" id="easy-booking"><section class="easy-block"><h2>${q.title}</h2><p>Select the options that best match the job.</p><div class="easy-options">${q.first.map((x,i)=>`<div class="easy-option"><input type="radio" name="detail" id="detail-${i}" value="${x}" ${i===0?'checked':''}><label for="detail-${i}">${x}</label></div>`).join('')}</div><div class="easy-options" style="margin-top:10px">${q.second.map((x,i)=>`<div class="easy-option"><input type="radio" name="size" id="size-${i}" value="${x}" ${i===0?'checked':''}><label for="size-${i}">${x}</label></div>`).join('')}</div></section><section class="easy-block"><h2>Where is the property?</h2><p>Enter only your postcode now - we ask for the full address in checkout.</p><div class="easy-field"><label>Postcode</label><input name="postcode" required placeholder="For example EH54 6AA"></div></section><section class="easy-block"><h2>Choose a date and time</h2><p>Pick the appointment that suits you.</p><div class="date-row"><div class="easy-field"><label>Preferred date</label><input name="date" type="date" required></div><div class="easy-field"><label>Arrival window</label><select name="time"><option>Morning - 8am-12pm</option><option>Afternoon - 12pm-5pm</option><option>Any time</option></select></div></div></section><button class="btn" style="width:100%">Add to booking and checkout -></button></form><aside class="easy-summary"><span class="basket-pill">Your booking</span><div class="order-service" style="margin-top:16px"><img src="${IMG[s.img]}" alt=""><div><small>Selected service</small><h3>${s.title}</h3></div></div><div class="price-big"><span>Total from<br><small>VAT included</small></span><strong>GBP ${gross.toFixed(2)}</strong></div><div class="summary-line"><span>Service</span><span>GBP ${net}</span></div><div class="summary-line"><span>VAT (20%)</span><span>GBP ${vat}</span></div><p class="marketplace-note">The exact total is confirmed before payment. No additional work is charged without approval.</p><button class="btn" form="easy-booking">Continue to checkout -></button><div class="mini-trust"><span>No account required</span><span>Secure Stripe payment</span><span>Email and SMS confirmation</span></div></aside></div></div></main>${easyCart(s,gross,net,vat)}${footer()}`}
function inlineBooking(s){const q=serviceQuestions(s),gross=startingPrices[s.slug],net=(gross/1.2).toFixed(2),vat=(gross-net).toFixed(2);return `<section class="inline-booking" id="book-online"><div class="wrap"><div class="inline-intro"><div><div class="eyebrow">Book without leaving this page</div><h2>Choose the details and appointment</h2><p>Everything needed before checkout is together here. Your full address and payment are requested only after you add the service to the cart.</p></div><span class="inline-step"><b>1</b> Details & date -> Cart & payment</span></div><div class="easy-grid"><form class="easy-form" id="easy-booking"><div class="inline-price-note">Included: ${s.title} from GBP ${gross.toFixed(2)} including VAT</div><section class="easy-block"><h3>${q.title}</h3><p>Select the options that best match the job.</p><div class="easy-options">${q.first.map((x,i)=>`<div class="easy-option"><input type="radio" name="detail" id="inline-detail-${i}" value="${x}" ${i===0?'checked':''}><label for="inline-detail-${i}">${x}</label></div>`).join('')}</div><div class="easy-options" style="margin-top:10px">${q.second.map((x,i)=>`<div class="easy-option"><input type="radio" name="size" id="inline-size-${i}" value="${x}" ${i===0?'checked':''}><label for="inline-size-${i}">${x}</label></div>`).join('')}</div></section><section class="easy-block"><h3>Postcode and appointment</h3><p>Check local availability and choose when you want us to attend.</p><div class="compact-grid"><div class="easy-field"><label>Postcode</label><input name="postcode" required placeholder="EH54 6AA"></div><div class="easy-field"><label>Preferred date</label><input name="date" type="date" required></div><div class="easy-field"><label>Arrival window</label><select name="time"><option>Morning - 8am-12pm</option><option>Afternoon - 12pm-5pm</option><option>Any time</option></select></div></div></section><button class="btn" style="width:100%">Add to booking - GBP ${gross.toFixed(2)} -></button></form><aside class="easy-summary"><span class="basket-pill">Booking summary</span><div class="order-service" style="margin-top:16px"><img src="${IMG[s.img]}" alt=""><div><small>Selected service</small><h3>${s.title}</h3></div></div><div class="price-big"><span>Total from<br><small>VAT included</small></span><strong>GBP ${gross.toFixed(2)}</strong></div><div class="summary-line"><span>Service</span><span>GBP ${net}</span></div><div class="summary-line"><span>VAT (20%)</span><span>GBP ${vat}</span></div><button class="btn" form="easy-booking">Add to booking -></button><div class="mini-trust"><span>No account needed</span><span>Address and payment in cart</span><span>No extra work without approval</span></div></aside></div></div></section>${easyCart(s,gross,net,vat)}`}
function easyCart(s,gross,net,vat){return `<div class="cart-overlay" id="easy-cart"><aside class="cart-drawer"><div class="cart-top"><div><div class="eyebrow">Your booking cart</div><h2 style="margin:4px 0">Address and payment</h2></div><button class="cart-close" aria-label="Close checkout">x</button></div><div class="cart-card"><div class="order-service"><img src="${IMG[s.img]}" alt=""><div><h3>${s.title}</h3><small id="cart-appointment">Appointment selected</small></div></div></div><form class="cart-card" id="easy-checkout"><h3>Your details</h3><div class="cart-form"><div class="easy-field"><label>Full name</label><input required name="name"></div><div class="easy-field"><label>Mobile number</label><input required name="phone" type="tel"></div><div class="easy-field"><label>Email address</label><input required name="email" type="email"></div><div class="easy-field"><label>Postcode</label><input required name="cartPostcode" id="cart-postcode"></div><div class="easy-field" style="grid-column:1/-1"><label>Address</label><input required name="address" placeholder="House number and street"></div></div><div class="cart-pay"><h3 style="margin-top:0">Secure payment</h3><div class="pay-options"><div class="pay-option">Debit / credit card</div><div class="pay-option">Apple Pay / Google Pay</div></div><div class="demo-warning">Demonstration only - no real card details are processed in this preview.</div><div class="cart-form"><div class="easy-field" style="grid-column:1/-1"><label>Card number</label><input disabled placeholder="**** **** **** ****"></div><div class="easy-field"><label>Expiry</label><input disabled placeholder="MM / YY"></div><div class="easy-field"><label>CVC</label><input disabled placeholder="***"></div></div></div><div class="summary-line"><span>Service</span><span>GBP ${net}</span></div><div class="summary-line"><span>VAT (20%)</span><span>GBP ${vat}</span></div><div class="cart-total"><span>Total to pay</span><span>GBP ${gross.toFixed(2)}</span></div><button class="btn" style="width:100%">Pay securely and confirm booking -></button><p class="marketplace-note">By paying, the customer agrees to the booking terms and cancellation policy.</p></form></aside></div>`}
function bindEasyBooking(s){const form=document.querySelector('#easy-booking'),cart=document.querySelector('#easy-cart');if(!form||!cart)return;form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;cart.classList.add('open');document.body.style.overflow='hidden';cart.querySelector('#cart-postcode').value=form.postcode.value;cart.querySelector('#cart-appointment').textContent=`${form.date.value} - ${form.time.value}`});cart.querySelector('.cart-close').onclick=()=>{cart.classList.remove('open');document.body.style.overflow=''};cart.querySelector('#easy-checkout').addEventListener('submit',e=>{e.preventDefault();const drawer=cart.querySelector('.cart-drawer');drawer.innerHTML=`<div class="quick-confirm"><div class="confirm-icon">OK</div><h2>Your booking is confirmed</h2><p>Stripe has verified payment and the booking has been created once.</p><span class="ref">Example booking: YT-2026-1042</span><div class="what-next"><div><strong>1. Confirmation</strong><br>Email and SMS sent</div><div><strong>2. Assignment</strong><br>Local professional assigned</div><div><strong>3. Updates</strong><br>Appointment progress shared</div></div><a class="btn" href="/" style="margin-top:25px">Return home</a></div>`})}
function mobileBookingBar(s){if(!s||!startingPrices[s.slug])return;const bar=document.querySelector('.sticky-mobile');if(!bar)return;const link=bar.querySelector('a:last-child');link.href='#book-online';link.textContent=`Book now - GBP ${startingPrices[s.slug].toFixed(2)}`;link.classList.add('mobile-book-cta')}
function home(){return `${header()}<main><section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Local people - Great results</div><h1>Local trades you can trust - from quick repairs to <em>complete renovations</em></h1><p class="lead">Qualified work for homes and landlords across Edinburgh, Livingston and nearby areas. One trusted team for repairs, heating, electrical and home improvements.</p><div class="hero-actions"><a class="btn" href="/contact">Get a free quote -></a><a class="btn outline" href="/services">Book a service</a></div><div class="trust-row"><span>Gas Safe registered</span><span>NICEIC approved</span><span>Fully insured</span></div></div><div class="hero-media"><img src="${IMG.kitchen}" alt="Newly renovated kitchen"><div class="rating">*****<br>Trusted local team</div></div></div></section>${quickQuote()}<section class="section mint"><div class="wrap"><div class="section-title"><div><div class="eyebrow">Start here</div><h2>What do you need help with?</h2></div><p>Choose the type of work and we will guide you to the right service.</p></div><div class="intent-grid">${[['Emergency repair','Fast help when you need it most','plumbing','Plumbing'],['Home improvement','Upgrade your home with confidence','renovation','Home Improvements'],['Boiler & heating','Keep your home warm and efficient','boiler','Boiler & Heating'],['Landlord services','Certificates and property support','landlord','Landlord Certificates']].map(x=>`<a class="intent" href="/services?category=${encodeURIComponent(x[3])}"><img src="${IMG[x[2]]}" alt=""><div><h3>${x[0]} -></h3><p>${x[1]}</p></div></a>`).join('')}</div><form class="availability"><input aria-label="Postcode" placeholder="Enter your postcode"><button class="btn">Check availability</button></form></div></section><section class="section"><div class="wrap"><div class="section-title"><div><div class="eyebrow">Most requested</div><h2>Popular services</h2></div><a class="btn outline" href="/services">View all services</a></div>${serviceCards(services.slice(0,3).concat([bySlug('plumbing-repairs'),bySlug('electrical-repairs'),bySlug('gas-safety-certificate')]))}</div></section>${trustStrip()}<section class="section soft"><div class="wrap split"><div class="split-media"><img src="${IMG.bathroom}" alt="Bathroom renovation"><img src="${IMG.kitchen}" alt="Kitchen renovation"></div><div><div class="eyebrow">Home improvements</div><h2>Transform your home with one trusted team</h2><p class="lead">From the first ideas to the finishing touches, your project is coordinated from start to finish.</p>${steps(['Free consultation','Detailed quote and plan','Installation and completion'])}<a class="btn" href="/contact">Request a home survey -></a></div></div></section><section class="section"><div class="wrap split"><div><div class="eyebrow">Boilers & heating</div><h2>A warmer, more efficient home starts here</h2><p class="lead">Get practical advice, a clear written quote and professional installation by Gas Safe engineers.</p><ul class="check-list"><li>Free boiler survey</li><li>Clear installation quote</li><li>Qualified local engineers</li><li>Warranty registration</li></ul><a class="btn" href="/services/new-boiler-installation">Get my boiler quote -></a></div><div class="hero-media"><img src="${IMG.boiler}" alt="Boiler installation"></div></div></section><section class="section mint"><div class="wrap"><div class="section-title"><div><div class="eyebrow">Straightforward from day one</div><h2>How Yes Trades works</h2></div></div>${steps(['Tell us about the job','Receive your clear quote','Choose a convenient date'])}</div></section>${reviews()} </main>${footer()}`}
function trustStrip(){return `<div class="trust-strip"><div class="wrap">${[['Pro','Qualified local trades'],['Quote','Clear written quotes'],['OK','Workmanship guaranteed'],['Phone','Support from start to finish']].map(x=>`<div class="trust-item"><span class="trust-icon">${x[0]}</span>${x[1]}</div>`).join('')}</div></div>`}
function steps(arr){return `<div class="steps">${arr.map((x,i)=>`<div class="step"><span class="step-num">${i+1}</span><div><h3>${x}</h3><p>${['Tell us what you need and when.','We explain the work, timescale and cost.','Our trusted team completes the work carefully.','We complete final checks and handover.'][i]}</p></div></div>`).join('')}</div>`}
function reviews(){return `<section class="section"><div class="wrap"><div class="section-title"><div><div class="eyebrow">Local customer feedback</div><h2>Trusted across West Lothian and Edinburgh</h2></div><a href="/reviews">Read all reviews -></a></div><div class="reviews">${[['Sarah M.','Edinburgh','"Excellent communication and a brilliant finish. The team respected our home throughout."'],['David R.','Livingston','"Everything was explained clearly and the work was completed exactly as agreed."'],['Karen T.','Bathgate','"Reliable, tidy and easy to deal with from the first call to completion."']].map(r=>`<article class="review"><div class="stars">*****</div><p>${r[2]}</p><strong>${r[0]}</strong><br><small>${r[1]}</small></article>`).join('')}</div></div></section>`}
function directory(){return `${header()}<main><section class="directory-hero"><div class="wrap"><div class="eyebrow">Repairs - Installations - Renovations</div><h1>Services for every part of your property</h1><p class="lead">Choose a category or browse every service. Clear information, the right booking journey and local support.</p><div class="filterbar">${groups.map((g,i)=>`<button class="chip ${i===0?'active':''}" data-filter="${g}">${g}</button>`).join('')}</div></div></section><section class="section"><div class="wrap" id="service-directory">${serviceCards(services)}</div></section></main>${footer()}`}
function servicePage(s){const action=s.flow==='survey'?'Request a free home survey':s.flow==='quote'?'Get my free quote':'Book this service';const actionUrl=s.flow==='book'?'#book-online':'#quote';const verb=s.flow==='book'?'booked at a convenient time':'planned around your property';return `${header()}<main><div class="wrap breadcrumbs"><a href="/">Home</a> > <a href="/services">Services</a> > ${s.title}</div><section class="page-hero"><div class="wrap page-hero-grid"><div><div class="eyebrow">${s.category}</div><h1>${headline(s)}</h1><p class="lead">${s.desc} Our local team keeps the work clear, respectful and ${verb}.</p><div class="hero-actions"><a class="btn" href="${actionUrl}">${action} -></a><a class="btn outline" href="tel:01316293987">Speak to our team</a></div><div class="trust-row"><span>Qualified trades</span><span>Clear written quote</span><span>Fully insured</span></div></div><div class="hero-media"><img src="${IMG[s.img]}" alt="${s.title}"><div class="rating">*****<br>Local, trusted support</div></div></div></section>${s.flow==='book'?inlineBooking(s):quickQuote(s.slug)}<nav class="anchorbar"><div class="wrap"><a href="#overview">Overview</a><a href="#included">What's included</a><a href="#process">Our process</a><a href="#faq">FAQs</a><a class="btn" href="${actionUrl}">${action}</a></div></nav><section id="overview" class="section"><div class="wrap"><div class="section-title"><div><div class="eyebrow">Complete local service</div><h2>Everything you need, handled properly</h2><p>We make it easy to understand what happens next and who is responsible at every stage.</p></div></div><div class="benefit-grid">${['Friendly first conversation','Qualified local professional','Clear scope and quotation','Careful completion'].map((x,i)=>`<div class="benefit"><span class="trust-icon">${['Phone','OK','Quote','Home'][i]}</span><h3>${x}</h3><p>${['Tell us what you need without technical jargon.','Your job is matched with the right skills.','Know what is included before work starts.','Respect for your property and a tidy finish.'][i]}</p></div>`).join('')}</div></div></section><section id="included" class="section soft"><div class="wrap split"><div><div class="eyebrow">What's included</div><h2>A clear service from first contact to completion</h2><ul class="check-list"><li>Initial requirements review</li><li>Professional assessment</li><li>Clear written quotation</li><li>Materials discussed in advance</li><li>Qualified workmanship</li><li>Progress communication</li><li>Final safety checks</li><li>Clean and tidy handover</li></ul></div><div class="hero-media"><img src="${IMG[s.img]}" alt="Professional ${s.title.toLowerCase()} service"></div></div></section><section id="process" class="section mint"><div class="wrap"><div class="section-title"><div><div class="eyebrow">How it works</div><h2>A straightforward process</h2></div></div>${steps(s.flow==='book'?['Choose your service','Confirm the details','Select a convenient time','Completion and confirmation']:['Tell us about your project','Survey or assessment','Receive your written quote','Work and handover'])}</div></section>${trustStrip()}${reviews()}${localSeoSection(s)}<section id="faq" class="section soft"><div class="wrap"><div class="section-title"><div><div class="eyebrow">Common questions</div><h2>${s.title} FAQs</h2></div></div>${faqData(s).map(x=>`<div class="faq"><button>${x[0]}<span>+</span></button><div>${x[1]}</div></div>`).join('')}</div></section><section id="quote" class="section"><div class="wrap quote-panel"><div class="contact-grid"><div><div class="eyebrow">Get started</div><h2>${action}</h2><p>Share a few details and our team will contact you to confirm the best next step.</p><form class="quote-form" onsubmit="event.preventDefault();this.innerHTML='<div class=\'full\'><h3>Thank you - your request is ready.</h3><p>This concept form demonstrates the confirmation state.</p></div>'"><input required placeholder="Your name"><input required type="tel" placeholder="Phone number"><input required type="email" placeholder="Email address"><input required placeholder="Postcode"><select class="full"><option>Preferred contact method</option><option>Phone</option><option>Email</option></select><textarea class="full" rows="4" placeholder="Tell us about the work"></textarea><button class="btn full">${action} -></button></form></div><aside class="contact-card"><h3>Prefer to speak to someone?</h3><p class="lead">0131 629 3987</p><p>Monday-Friday: 8am-6pm<br>Saturday: 9am-2pm</p><hr><p>Serving Edinburgh, Livingston, Bathgate, Broxburn, Linlithgow and surrounding areas.</p></aside></div></div></section></main>${footer()}`}
function headline(s){if(s.slug==='bathroom-renovation')return 'Bathroom renovations designed around <em>your home</em>';if(s.slug==='kitchen-renovation')return 'A practical kitchen, beautifully <em>built around you</em>';if(s.slug==='new-boiler-installation')return 'A warmer, more efficient home starts with the <em>right boiler</em>';return `${s.title}, delivered by a <em>trusted local team</em>`}
function localSeoSection(s){const related=services.filter(x=>x.category===s.category&&x.slug!==s.slug).slice(0,5);return `<section class="section"><article class="wrap seo-copy"><div class="eyebrow">Local ${s.category.toLowerCase()} specialists</div><h2>${s.title} in Edinburgh, Livingston and West Lothian</h2><p>Yes Trades provides ${s.title.toLowerCase()} for homeowners, landlords and property managers across Edinburgh, Livingston, Bathgate, Broxburn, Linlithgow and nearby areas. We explain the next step clearly and match the work with an appropriately skilled local trade professional.</p><h3>Related ${s.category.toLowerCase()} services</h3><div class="related-links">${related.map(x=>`<a href="/services/${x.slug}">${x.title}</a>`).join('')}<a href="/areas">Check areas we cover</a></div></article></section>`}
function faqData(s){return [[`How does the ${s.title.toLowerCase()} process start?`,'Tell us what you need online or by phone. We will confirm whether the next step is a booking, assessment or home survey.'],['Will I receive a written quotation?','Yes. Where a quotation is required, the scope, assumptions and price will be set out clearly before work starts.'],['Which areas do you cover?','We serve Edinburgh, Livingston and surrounding areas across West Lothian. Availability is confirmed from your postcode.'],['Are your trades qualified and insured?','Jobs are assigned to appropriately qualified professionals and relevant registration details can be confirmed for your work.'],['How soon can the work be completed?','Timescales depend on the service, materials and availability. We will provide a realistic date before you commit.']]}
function simplePage(type){const data={
 about:['About Yes Trades','One local team for repairs, improvements and property compliance.','Yes Trades supports homeowners, landlords and property managers across Edinburgh and West Lothian. We bring different trades together with clear communication and practical support from the first enquiry to completion.'],
 landlords:['Property support for landlords','Certificates, maintenance and reliable communication in one place.','Arrange compliance certificates, repairs, maintenance and property preparation without chasing multiple providers.'],
 reviews:['Reviews from local customers','Real experiences across Edinburgh and West Lothian.','Read how customers found our communication, workmanship and service from first contact through to completion.'],
 areas:['Areas we cover','Local support across Edinburgh and West Lothian.','We serve Edinburgh, Livingston, Bathgate, Broxburn, Linlithgow and surrounding communities. Enter your postcode to confirm availability.'],
 contact:['Talk to the Yes Trades team','Tell us what you need and we will guide you to the right next step.','Call, email or use the enquiry form. For a renovation or installation, we can arrange a survey; for smaller work, we can help you book a convenient time.']};const d=data[type];return `${header()}<main><section class="directory-hero"><div class="wrap"><div class="eyebrow">Yes Trades</div><h1>${d[0]}</h1><p class="lead">${d[1]}</p></div></section><section class="section"><div class="wrap contact-grid"><div><h2>${type==='contact'?'Send an enquiry':'Local people. Clear service. Great results.'}</h2><p class="lead">${d[2]}</p>${type==='landlords'?serviceCards(services.filter(x=>x.category==='Landlord Certificates')):type==='reviews'?'<div class="reviews">'+[['Sarah','Edinburgh'],['David','Livingston'],['Karen','Bathgate'],['Amelia','Broxburn'],['Iram','Livingston'],['James','Edinburgh']].map(r=>`<article class="review"><div class="stars">*****</div><p>"Friendly communication, clear timing and professional work throughout."</p><strong>${r[0]}</strong><br>${r[1]}</article>`).join('')+'</div>':type==='areas'?'<div class="filterbar">'+['Edinburgh','Livingston','Bathgate','Broxburn','Linlithgow','Musselburgh','Dalkeith','Kirkliston'].map(x=>`<span class="chip">- ${x}</span>`).join('')+'</div>':''}</div>${type==='contact'?`<div class="quote-panel"><form class="quote-form"><input placeholder="Name"><input placeholder="Phone"><input placeholder="Email"><input placeholder="Postcode"><select class="full"><option>What do you need help with?</option>${groups.slice(1).map(x=>`<option>${x}</option>`)}</select><textarea class="full" rows="5" placeholder="Tell us about the job"></textarea><button class="btn full">Send my enquiry -></button></form></div>`:`<aside class="contact-card"><h3>Need help choosing?</h3><p>Our team can guide you to the right service.</p><a class="btn" href="/contact">Contact us -></a></aside>`}</div></section>${type==='about'?trustStrip()+reviews():''}</main>${footer()}`}
function legal(type){return `${header()}<main><section class="directory-hero"><div class="wrap"><h1>${type==='privacy'?'Privacy policy':'Terms and conditions'}</h1><p>Last updated: September 2026</p></div></section><section class="section"><article class="wrap legal"><p>This prototype page shows where the company's reviewed legal text will appear. It should be replaced with the approved Yes Trades policy before publication.</p><h2>Information and scope</h2><p>Clear information should explain who operates the website, how customers can contact the company, and which services and booking terms apply.</p><h2>Customer information</h2><p>Describe how enquiries, bookings, quotations, payments and service communications are handled.</p><h2>Your choices and rights</h2><p>Explain applicable customer rights, cancellation arrangements and privacy choices in clear language.</p><h2>Contact</h2><p>Questions can be sent through the contact page or discussed with the Yes Trades team.</p></article></section></main>${footer()}`}
function route(){const path=location.pathname.replace(/\/$/,'')||'/';let html;let currentService=null;if(path==='/')html=home();else if(path.startsWith('/book/')){currentService=bySlug(path.split('/').pop());html=currentService?easyBookingPage(currentService):directory()}else if(path==='/services')html=directory();else if(path.startsWith('/services/')){currentService=bySlug(path.split('/').pop());html=currentService?servicePage(currentService):directory()}else if(['/about','/landlords','/reviews','/areas','/contact'].includes(path))html=simplePage(path.slice(1));else if(['/privacy','/terms'].includes(path))html=legal(path.slice(1));else html=`${header()}<main class="section"><div class="wrap"><h1>Page not found</h1><a class="btn" href="/">Return home</a></div></main>${footer()}`;document.querySelector('#app').innerHTML=html;setSEO(path,currentService);bind();if(currentService&&startingPrices[currentService.slug]&&document.querySelector('#easy-booking')){bindEasyBooking(currentService);mobileBookingBar(currentService)}}
function bind(){const finder=document.querySelector("#quick-finder");if(finder)finder.onsubmit=e=>{e.preventDefault();showQuote(finder)};document.querySelectorAll('.faq button').forEach(b=>b.onclick=()=>b.parentElement.classList.toggle('open'));const m=document.querySelector('.menu-btn');if(m)m.onclick=()=>{const n=document.querySelector('.navlinks');n.style.display=n.style.display==='flex'?'none':'flex';n.style.position='absolute';n.style.top='66px';n.style.left='0';n.style.right='0';n.style.background='#fff';n.style.padding='22px';n.style.flexDirection='column'};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const items=b.dataset.filter==='All'?services:services.filter(s=>s.category===b.dataset.filter);document.querySelector('#service-directory').innerHTML=serviceCards(items)});const q=new URLSearchParams(location.search).get('category');if(q){const b=[...document.querySelectorAll('[data-filter]')].find(x=>x.dataset.filter===q);if(b)b.click()}}
route();
